/**
 * Data source selection: real synced data or the shipped demo data – never both.
 *
 * As soon as one synced ride exists in src/content/rides/, every page reads the real
 * data (src/content/*, public/streams, src/data). Without real rides the site shows the
 * synthetic demo dataset from demo/ (generated by `npm run demo:generate`).
 * The sync only ever touches the real locations; demo/ is read-only for the app.
 * `DATA_SOURCE=demo` forces the demo dataset (e2e tests, screenshots) without touching real data.
 */
import fs from 'node:fs';
import path from 'node:path';

/** Tracked folder with the synthetic demo dataset (relative to the project root). */
export const DEMO_DIR = 'demo';

/** True if `dir` (recursively) contains at least one ride Markdown file. */
function hasRideFiles(dir) {
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return false; }
  for (const e of entries) {
    if (e.isFile() && e.name.endsWith('.md')) return true;
    if (e.isDirectory() && hasRideFiles(path.join(dir, e.name))) return true;
  }
  return false;
}

/**
 * @returns {{ demo: boolean, ridesDir: string, gearDir: string, streamsDir: string, dataDir: string }}
 *   absolute folders for rides, gear, streams and JSON data (athlete, goals, fitness history).
 */
export function selectDataSource({ root = process.cwd(), env = process.env } = {}) {
  const realRides = path.join(root, 'src/content/rides');
  if (env.DATA_SOURCE !== 'demo' && hasRideFiles(realRides)) {
    return {
      demo: false,
      ridesDir: realRides,
      gearDir: path.join(root, 'src/content/gear'),
      streamsDir: path.join(root, 'public/streams'),
      dataDir: path.join(root, 'src/data'),
    };
  }
  const demo = path.join(root, DEMO_DIR);
  return {
    demo: true,
    ridesDir: path.join(demo, 'rides'),
    gearDir: path.join(demo, 'gear'),
    streamsDir: path.join(demo, 'streams'),
    dataDir: path.join(demo, 'data'),
  };
}
